// Per-champion spell behaviour for the teamfight AI (owner: kits agent).
// Data comes from kits.gen.ts (generated by scripts/build_kits.py from Data Dragon + Meraki + LCK 2026 timelines +
// hand overrides). Champions missing from the generated table (new / renamed) get a fallback derived from
// champions.json, so kitFor() always returns a usable kit.
import type { ChampionData } from "../data/types";
import type { ChampionKit, FightRole, SpellKit } from "./kit-types";
import { KITS } from "./kits.gen";

const cache = new Map<string, ChampionKit>();

function roleOf(c: ChampionData): FightRole {
  const t = c.tags;
  if (t.includes("Tank")) return "frontline";
  if (t.includes("Assassin")) return "assassin";
  if (t.includes("Marksman")) return "backline";
  if (t.includes("Support") && c.style.peel >= 6) return "enchanter";
  if (t.includes("Fighter")) return "skirmisher";
  if (t.includes("Mage")) return c.style.poke >= 8 && c.attackRange >= 525 ? "artillery" : "backline";
  return "skirmisher";
}

/** Kit built only from champions.json (used for champions the generator has not seen). */
export function fallbackKit(c: ChampionData): ChampionKit {
  const spells: SpellKit[] = c.spells.map((sp, i) => {
    const friendly = sp.vfx === "shield" || sp.vfx === "heal";
    const mobile = sp.vfx === "dash" || sp.vfx === "blink" || sp.also === "dash" || sp.also === "blink";
    const knock = sp.vfx === "knockup" || sp.also === "knockup";
    const ult = i === 3;
    const uses: SpellKit["uses"] = friendly
      ? [sp.vfx === "heal" ? "heal" : "shield"]
      : mobile
        ? sp.cc ? ["engage", "cc", "gapclose"] : ["gapclose", "escape"]
        : sp.cc ? ["cc", "dps"] : ["dps"];
    return {
      key: sp.key,
      slot: i as 0 | 1 | 2 | 3,
      uses,
      target: friendly ? "ally" : sp.vfx === "self" || sp.vfx === "stealth" ? "self" : sp.vfx === "target" ? "enemy" : sp.vfx === "line" || sp.vfx === "cone" ? "direction" : "area",
      shape: sp.vfx,
      range: sp.range > 0 && sp.range < 5000 ? sp.range : 600,
      radius: sp.radius ?? 0,
      width: sp.width,
      cc: sp.cc ? { type: knock ? "knockup" : "stun", dur: ult ? 1.25 : 0.75 } : undefined,
      dash: mobile ? { len: Math.min(sp.range || 450, 600), to: sp.vfx === "target" ? "target" : "direction", overWalls: sp.vfx === "blink" || sp.also === "blink" } : undefined,
      dmg: friendly ? 0 : sp.power || 1,
      support: friendly ? sp.power || 1 : undefined,
      delay: sp.vfx === "line" || sp.vfx === "circle" || sp.vfx === "global" ? 0.5 : 0.25,
      skillshot: sp.vfx === "line" || sp.vfx === "cone" || sp.vfx === "circle" || sp.vfx === "global" || sp.vfx === "wall",
      cd: sp.cd || (ult ? 100 : 10),
      minTargets: ult && sp.cc && (sp.radius ?? 0) >= 250 && !mobile ? 2 : undefined,
    };
  });
  return { id: c.id, role: roleOf(c), spells };
}

/**
 * The fight AI's view of a champion's kit. Generated data when available; `shape` always follows the live
 * champions.json `vfx` (the renderer draws by it), and spells missing from the generated kit fall back.
 */
export function kitFor(c: ChampionData): ChampionKit {
  const hit = cache.get(c.id);
  if (hit) return hit;
  const gen = KITS[c.id];
  let kit: ChampionKit;
  if (!gen) {
    kit = fallbackKit(c);
  } else {
    let fb: ChampionKit | null = null;
    const spells = c.spells.map((sp, i): SpellKit => {
      const g = gen.spells.find((s) => s.key === sp.key) ?? (fb ??= fallbackKit(c)).spells[i];
      return g.shape === sp.vfx ? g : { ...g, shape: sp.vfx };
    });
    kit = { ...gen, spells };
  }
  cache.set(c.id, kit);
  return kit;
}

/** True when the champion has a generated (data-backed) kit rather than the champions.json fallback. */
export function hasGeneratedKit(id: string): boolean {
  return id in KITS;
}
